# 条件概率探索台
mode = 1   # 条件：1=偶数 2=奇数 3=大于3 4=无条件

hide()
# 六个骰面
i = 1
while i < 7:
    x = -150 + (i - 1) * 60
    col = "#94a3b8"
    keep = 1
    if mode == 1:
        if i == 1:
            keep = 0
        if i == 3:
            keep = 0
        if i == 5:
            keep = 0
        col = "#e2e8f0"
    if mode == 2:
        if i == 2:
            keep = 0
        if i == 4:
            keep = 0
        if i == 6:
            keep = 0
        col = "#e2e8f0"
    if mode == 3:
        if i < 4:
            keep = 0
        col = "#e2e8f0"
    if keep == 1:
        col = "#fdba74"
    fill_rect(x, 40, 46, 46, col)
    write(i, x, 40, "#0f172a", 16)
    i = i + 1
# 条件下的总数与出6概率
n = 6
if mode == 1:
    n = 3
if mode == 2:
    n = 3
if mode == 3:
    n = 3
if mode == 2:
    write("奇数条件下不可能出 6：P=0", -100, -60, "#dc2626", 13)
if mode != 2:
    write("条件下的样本数：" + n + " 个（橙色）", -120, -40, "#b45309", 12)
    write("P(出6 | 条件) = 1/" + n, -100, -70, "#dc2626", 14)
if mode == 4:
    write("无条件：P(出6) = 1/6", -100, -70, "#1d4ed8", 14)
write("P(A|B) = P(A且B) / P(B)：信息让概率更准", -200, 150, "#1d4ed8", 12)
write("新信息 → 缩小样本空间 → 重新分配概率", -200, 125, "#16a34a", 11)

